function sourceReadings(book){const leads=TOPIC_READING_LEADS[state.topic]||{};const terms=topic().keywords.split(/\s+/).filter(w=>w.length>1);const rows=SEED.readings.filter(r=>r.locales?.[getLocale()]).map(r=>({r,score:(leads[r.id]?100:0)+terms.reduce((n,w)=>n+([r.title?.[getLocale()],r.summary?.[getLocale()]].join(' ').toLowerCase().includes(w.toLowerCase())?1:0),0)})).filter(x=>x.score>0).sort((a,b)=>b.score-a.score||a.r.id.localeCompare(b.r.id)).slice(0,4);return '<section class="section"><h3>'+pair('解释阅读','Explanation reading')+'</h3><p>'+pair('按当前主题匹配已发布说明；机制解释不是所选地区的现况证据。','Published explanations matched to this topic; mechanisms are not evidence of current conditions in the selected area.')+'</p>'+rows.map(({r})=>{const u=new URL(r.href,location.origin);u.searchParams.set('locale',getLocale());u.hash=location.hash;return '<article><a class="source-reading-link" href="'+esc(u.pathname+u.search+u.hash)+'">'+esc(r.title[getLocale()])+'</a><p class="small">'+esc(r.summary[getLocale()])+'</p><small>'+esc(leads[r.id]?vtext(leads[r.id]):pair('延伸阅读 · 与主题文字相关，适用范围请见正文。','Further reading · Topic-related text; consult the reading for its scope.'))+'</small></article>'}).join('')+(rows.length?'':'<p>'+pair('尚无匹配的主题解释，请搜索更多资料。','No matching topic explanation yet. Search more material.')+'</p>')+'<a href="#world-search" data-action="sourceCatalogue">'+pair('更多资料与搜索','More material and search')+'</a></section>';}
