const REGION_EN={EAST_ASIA:'East Asia',SOUTH_ASIA:'South Asia',SOUTHEAST_ASIA:'Southeast Asia',WEST_ASIA:'West Asia',CENTRAL_ASIA:'Central Asia',EUROPE:'Europe',MEDITERRANEAN:'Mediterranean',AFRICA:'Africa',NORTH_AFRICA:'North Africa',SUB_SAHARAN_AFRICA:'Sub-Saharan Africa',AMERICAS:'Americas',NORTH_AMERICA:'North America',SOUTH_AMERICA:'South America',OCEANIA:'Oceania',GLOBAL:'Global / cross-regional'};
Object.assign(REGION_ZH,{ASIA:'亚洲',EURASIA:'欧亚',EAST_AFRICA:'东非',WEST_AFRICA:'西非'});Object.assign(REGION_EN,{ASIA:'Asia',EURASIA:'Eurasia',EAST_AFRICA:'East Africa',WEST_AFRICA:'West Africa'});
let state={lang:getLocale()==='zh-Hans'?'zh':'en',mode:'current',pane:'map',space:'explore',region:'GLOBAL',topic:'connections',year:2026,baseline:'IDN',scale:'place',perspective:'general',caseId:'CA-T11-02',caseRight:'CA-T06-02',caseRegion:'',casePeriod:'',caseSearch:'',applyYear:false,caseLimit:8,snapshot:db.snapshots[0]?.snapshotId||'',fig:'13F',book:0,scenario:0,cell:0,lifeFocus:'time',origin:'world'};
let customQuestion='',askQuestion='',searchText='',searchResults=null,remoteImages=true,selectedImageRole='CASE_HERO',mapZoom=1,mapPan=0,controlsBusy=false,pending=null;
let privateData={self:'',method:'',profile:'',goal:'',options:'',attempt:'',result:'',review:''}, consent={self:false,method:false,profile:false},consentGranted=false,navGranted=false,navStep='goal',privatePreview=false,reviewExport=null;
let dataRequestSequence=0;
let evidenceIntent='',evidenceQuarter='',answerSequence=0,answerSignature='';
const answerHost=document.createElement('section');answerHost.id='worldEvidenceAnswer';answerHost.className='panel';answerHost.hidden=true;answerHost.setAttribute('aria-live','polite');answerHost.setAttribute('tabindex','-1');$('#searchResults').after(answerHost);

const observations=new Map(),localImages=new Map(),loadedDocuments=new Map();let readBusy=false,importReport=null,networkStatus='',dataRequestState='',activeRead=null;
const nameGeo=id=>id==='GLOBAL'?T('global'):(GEO.find(g=>g.id===id)?.name[state.lang]||T('none'));
const country=id=>GEO.find(g=>g.id===id), caseById=id=>db.cases.find(c=>c.caseId===id), vtext=a=>a[state.lang==='zh'?0:1], topic=()=>TOPICS[state.topic];
const yearText=n=>!Number.isInteger(n)?T('notLoaded'):n<0?pair(`公元前${Math.abs(n)}年`,`${Math.abs(n)} BCE`):pair(`公元${n}年`,`${n} CE`);
const span=c=>{const w=c?.timeWindow||c?.timeRange;return w?(w.approximate?pair('约 ','c. '):'')+yearText(w.startYear)+' — '+yearText(w.endYear):T('notLoaded')};
const readable=c=>!!c&&Object.keys(FIELDS).some(k=>text(c[k]));
const caseTitle=c=>text(c?.title)||T('notLoaded');
const field=(c,k)=>text(c?.[k]);
const figureLabel=id=>FIGURES[id]?.label[state.lang]||id;
const q=()=>customQuestion||vtext(topic().question);
function publicContext(){return {region:state.region,topic:state.topic,year:state.year,baseline:state.baseline,scale:state.scale,perspective:state.perspective,lang:state.lang,mode:state.mode,pane:state.pane,caseId:state.caseId,caseRight:state.caseRight,fig:state.fig,snapshot:state.snapshot};}
function publicText(includeCustom=false){let s=[q(),`${T('region')}: ${nameGeo(state.region)}`,`${T('topic')}: ${vtext(topic().name)}`,`${T('period')}: ${yearText(state.year)}`,`${T('compareBase')}: ${nameGeo(state.baseline)}`,`${T('scale')}: ${T('scale'+({place:'Place',city:'City',network:'Network'}[state.scale]))}`,T('publicOnly')];if(!includeCustom)s[0]=vtext(topic().question);return s.join('\n');}
function safeURL(s){try{let u=new URL(s);return u.protocol==='https:'&&!u.username&&!u.password?u.href:''}catch{return ''}}
function external(url,label,cls=''){url=safeURL(url);return url?`<a href="${esc(url)}" target="_blank" rel="noopener noreferrer" class="${cls}">${esc(label)}</a>`:'';}
function sourceLink(path,label){return siteLink('/'+path,label,'');}
function siteLink(path,label,cls='btn'){const u=new URL(path,location.origin);u.searchParams.set('locale',state.lang==='zh'?'zh-Hans':'en');return `<a class="${esc(cls)}" href="${esc(u.pathname+u.search+u.hash)}">${esc(label)}</a>`}
function button(action,label,extra='',cls=''){return `<button data-action="${action}" ${extra} class="${cls}">${esc(label)}</button>`}
function figureButtons(ids){return `<div class="actions">${ids.filter(id=>FIGURES[id]).map(id=>button('figure',figureLabel(id),`data-id="${id}"`)).join('')}</div>`}
function toast(msg){$('#toast').textContent=msg;$('#toast').hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').hidden=true,4200)}
function translateShell(){document.title=pair('PHI OS · 世界探索','PHI OS · World experience');$$('[data-t]').forEach(e=>e.textContent=T(e.dataset.t));$('#heroTitle').innerHTML=pair('世界如何运行，<br><span>又如何影响你？</span>','How does the world work,<br><span>and how does it affect you?</span>');$('#language').textContent=pair('语言 · 中文','Language · English');$('#language').ariaLabel=pair('切换为英文界面','Switch to Chinese interface');$('#globalSearch').placeholder=pair('例如：马来西亚、粮食价格、产业变化','For example: Malaysia, food prices, industrial change');$('#globalSearch').ariaLabel=T('searchLabel');$('#globalSearch').value=searchText;$('#quick').ariaLabel=pair('快捷入口','Quick entry points');$('#sharedContext').ariaLabel=pair('当前探索条件','Shared exploration context');$('#mainNav').ariaLabel=pair('主要阅读方向','Main reading perspectives');$('#imageNetwork').textContent=T(remoteImages?'disableImages':'enableImages');}
function renderContext(){const select=(id,value,options)=>'<select id="'+id+'">'+options.map(([k,n])=>'<option value="'+k+'" '+(value===k?'selected':'')+'>'+esc(n)+'</option>').join('')+'</select>';$('#sharedContext').innerHTML='<label>'+T('region')+select('regionSelect',state.region,[['GLOBAL',T('global')],...GEO.map(g=>[g.id,g.name[state.lang]])])+'</label><label>'+T('topic')+select('topicSelect',state.topic,Object.entries(TOPICS).map(([k,t])=>[k,vtext(t.name)]))+'</label><div class="context-foot"><strong>'+esc(nameGeo(state.region))+' · '+esc(vtext(topic().name))+' · '+yearText(state.year)+'</strong>'+button('pane',T('explore'),'data-pane="map"','primary')+'</div><details class="world-more"><summary>'+pair('更多条件','More conditions')+'</summary><label>'+T('period')+'<input id="yearSelect" type="number" min="-12000" max="2100" value="'+state.year+'"></label><p>'+pair('按指定年份读取；当前接口不支持自动寻找最新值。空缺不会以其他年份替代。','Exact-year lookup; automatic latest-value lookup is not supported. Missing years are not substituted.')+'</p><label>'+T('scale')+select('scaleSelect',state.scale,[['place',T('scalePlace')],['city',T('scaleCity')],['network',T('scaleNetwork')]])+'</label>'+ (state.pane==='life'?'<label>'+T('perspective')+select('perspectiveSelect',state.perspective,['general','worker','caregiver','business','student'].map(k=>[k,T(k)]))+'</label>':'')+button('reset',T('reset'))+'</details>';}
function renderQuick(){ $('#quick').hidden=true;$('#quick').innerHTML=[['map',pair('探索地图','Explore map')],['data',T('current')],['history',pair('历史变化','Explore history')],['compare',pair('国家与地区比较','Compare areas')],['economy',pair('资源与经济','Resources & economy')],['me',pair('世界与我的生活','World × my life')]].map(([id,tx])=>button('quick',tx,`data-target="${id}"`)).join('')}
function nav(){return ['current','history','compare'].map(m=>`<button role="tab" id="tab-${m}" aria-controls="exploreView" aria-selected="${state.space==='explore'&&state.mode===m}" tabindex="${state.mode===m?0:-1}" data-action="mode" data-mode="${m}">${T(m)}</button>`).join('')}
function subNav(items){return `<div class="subnav">${items.map(([pane,key])=>`<button data-action="pane" data-pane="${pane}" aria-pressed="${state.pane===pane}">${T(key)}</button>`).join('')}</div>`}
function topicBar(){return `<div class="topicbar">${Object.entries(TOPICS).map(([id,t])=>`<button data-action="topic" data-topic="${id}" aria-pressed="${state.topic===id}">${esc(vtext(t.name))}</button>`).join('')}</div>`}
function mapHTML(){const g=country(state.region),pt=g?`<circle class="mappin" cx="${g.x}" cy="${g.y}" r="4.5"/><text class="maplabel" text-anchor="${g.x>920?'end':'start'}" x="${g.x+(g.x>920?-10:10)}" y="${g.y-11}">${esc(nameGeo(state.region))}</text>`:'';let gr='';for(let x=90;x<1080;x+=90)gr+=`<path d="M${x} 0V440"/>`;for(let y=45;y<440;y+=90)gr+=`<path d="M0 ${y}H1080"/>`;
return `<section class="stage"><div class="stagehead"><div><h3>${T('mapTitle')}</h3><p class="small muted compact">${T('mapSub')}</p></div><span class="pilltag">${T('locationOnly')}</span></div><div class="map-layout"><div class="mapbox"><div class="maptoolbar">${button('zoomIn','+',`aria-label="${T('zoomIn')}"`)}${button('zoomOut','−',`aria-label="${T('zoomOut')}"`)}${button('mapReset',T('zoomReset'))}${button('focus',T('zoomFocus'),state.region==='GLOBAL'?'disabled':'')}${button('panLeft','←',`aria-label="${T('panLeft')}"`)}${button('panRight','→',`aria-label="${T('panRight')}"`)}</div><svg id="worldMap" viewBox="0 0 1080 440" role="group" aria-label="${T('mapTitle')}"><g class="grid">${gr}</g><g id="mapTransform">${GEO.map(a=>`<path class="land ${a.id===state.region?'selected':a.id===state.baseline?'baseline':''}" d="${a.d}" data-region="${a.id}" role="button" tabindex="${a.id===(state.region==='GLOBAL'?'MYS':state.region)?'0':'-1'}" aria-label="${esc(a.name[state.lang])}"><title>${esc(a.name[state.lang])}</title></path>`).join('')}${pt}</g></svg><div class="map-prompt">${T('mapTap')}</div></div><aside class="mapaside"><div class="eyebrow">${T('region')}</div><h3>${esc(nameGeo(state.region))}</h3><p class="muted">${T(state.region==='GLOBAL'?'regionPrompt':'regionSelected')}</p><div class="topic-note"><span class="pilltag">${T('topicReading')}</span><h3 style="font:550 17px system-ui;margin-top:13px">${esc(vtext(topic().name))}</h3><p>${esc(vtext(topic().qs[0]))}</p></div><div class="actions">${button('compareArea',T('compareAction'),state.region==='GLOBAL'?'disabled':'')}${button('relatedHistory',T('historyAction'))}${button('pane',T('lifeAction'),'data-pane="life"')}</div></aside></div><div class="mapcaption"><span><i class="legend-dot"></i>${T('mapLegend')}</span><span><i class="legend-dot blue"></i>${T('baselineLegend')}</span><span>${T('mapCaveat')} ${external('https://www.naturalearthdata.com/about/',T('mapSource'))}</span></div><div class="storystrip"><h3>${esc(vtext(topic().question))}</h3><p class="small muted">${T('lifeIntro')}</p><div class="flow">${topic().steps.map((s,i)=>`${i?'<span class="arrow" aria-hidden="true">→</span>':''}<div class="node">${esc(vtext(s))}</div>`).join('')}</div><div class="actions">${button('pane',T('data'),'data-pane="data"')}${button('pane',T('lifeAction'),'data-pane="life"')}${button('pane',T('ask'),'data-pane="ask"')}</div></div></section>`}
function applyMapTransform(){let el=$('#mapTransform');if(!el)return;let p=country(state.region),cx=p?.x||540,cy=p?.y||225;el.setAttribute('transform',`translate(${540-cx*mapZoom+mapPan},${220-cy*mapZoom}) scale(${mapZoom})`);if(mapZoom===1&&mapPan===0)el.removeAttribute('transform')}
const obsKey=(id,i,y)=>[id,i,y].join('|');
function obsCell(id,i){const o=observations.get(obsKey(id,i.id,state.year));if(!o)return `<span class="metric-missing">${T('notLoaded')}</span>`;if(o.status!=='value')return `<span class="metric-missing">${T(o.status==='missing'?'noRecord':'readFailed')}</span>`;return `<span class="metric">${new Intl.NumberFormat(state.lang==='zh'?'zh-Hans':'en',{maximumFractionDigits:i.id==='SP.POP.TOTL'?0:2,notation:o.value>=1e9?'compact':'standard'}).format(o.value)}</span><small class="muted">${esc(vtext(i.unit))}</small><details class="sourcesdetails"><summary>${T('sourceRecord')}</summary><p>${T('value')}: ${new Intl.NumberFormat(state.lang==='zh'?'zh-Hans':'en',{maximumFractionDigits:2}).format(o.value)}</p><p>${T('observed')}: ${o.year}</p><p>${T('retrieved')}: ${esc(o.retrievedAt)}</p><p>${T('sourceUpdated')}: ${esc(o.lastupdated||T('notLoaded'))}</p>${external(o.url,pair('世界银行原始记录','World Bank source response'))}</details>`}
function areaOptions(sel){return GEO.filter(g=>g.iso2).map(g=>`<option value="${g.id}" ${g.id===sel?'selected':''}>${esc(g.name[state.lang])}</option>`).join('')}
function dataView(compare=false){return `${compare?`<div class="actions" style="margin-bottom:16px">${button('pane',pair('返回地图 · 保留当前条件','Back to map · Keep current selections'),'data-pane="map"')}</div>`:''}<div class="note">${T('dataIntro')}</div><section class="panel"><h3>${esc(vtext(topic().name))} · ${pair('尚缺资料','Coverage gap')}</h3><p>${pair('尚未接入此主题的地区年度指标。下方人口与 GDP 仅为地区背景，不代表当前主题的事实覆盖。','Regional annual indicators for this topic are not connected. Population and GDP below are regional background, not topic evidence.')}</p></section><h3>${pair('地区背景','Regional background')}</h3>${compare?`<div class="duo"><label>${T('left')}<select id="dataLeft" style="width:100%;padding:10px"><option value="GLOBAL" ${state.region==='GLOBAL'?'selected':''}>${T('global')}</option>${areaOptions(state.region)}</select></label><label>${T('right')}<select id="dataRight" style="width:100%;padding:10px">${areaOptions(state.baseline)}</select></label></div>`:''}<div class="sectiontop"><h3>${esc(nameGeo(state.region))}${compare?' / '+esc(nameGeo(state.baseline)):''} · ${yearText(state.year)}</h3>${button(compare?'readCompareData':'readData',readBusy?T('readingData'):T('readData'),readBusy?'disabled':'','primary')}</div>${compare&&state.region===state.baseline?`<p class="note">${T('samePlace')}</p>`:''}<div class="table-scroll"><table class="comparison-table"><thead><tr><th>${T('metricLabel')}</th><th>${esc(nameGeo(state.region))}</th>${compare?`<th>${esc(nameGeo(state.baseline))}</th>`:''}</tr></thead><tbody>${INDICATORS.map(i=>`<tr><th scope="row">${esc(vtext(i.label))}<small class="muted" style="display:block">${esc(vtext(i.unit))}</small></th><td>${obsCell(state.region,i)}</td>${compare?`<td>${obsCell(state.baseline,i)}</td>`:''}</tr>`).join('')}</tbody></table></div><p class="statusline" role="status">${esc(dataRequestState)}</p><p class="small muted">${T(compare?'noScores':'wbScope')}</p><p class="small muted">${T('wbPrivacy')}</p><div class="panel" style="margin-top:18px"><h3>${T('readingQuestions')}</h3>${topic().qs.map(q=>`<p>${esc(vtext(q))}</p>`).join('')}<p class="small muted">${T('wbScope')}</p>${external('https://datahelpdesk.worldbank.org/knowledgebase/articles/889392',pair('指标接口说明','Indicators API documentation'))}</div><div class="section">${figureButtons(topic().figs.slice(0,3))}</div>`}
function assetFor(id,role='CASE_HERO'){return db.assets.find(a=>a.subjectId===id&&a.family===role)}
function validKey(k){return typeof k==='string'&&k.startsWith('images/')&&!/[\\?#]/.test(k)&&!k.split('/').some(x=>!x||x==='.'||x==='..')&&/\.(webp|png|jpe?g)$/i.test(k)}
function registeredURL(a){if(!a||!validKey(a.bucketKey))return '';try{const u=new URL(a.publicUrl);return u.origin===R2&&decodeURIComponent(u.pathname)==='/'+a.bucketKey&&!u.search&&!u.hash?u.href:''}catch{return ''}}
function assetSource(a){const l=localImages.get(a?.assetId);if(l&&l.sha256===a.sha256)return l.url;if(/^data:image\/(webp|png|jpeg);base64,[A-Za-z0-9+/=]+$/.test(a?._embeddedImage||''))return a._embeddedImage;return remoteImages?registeredURL(a):''}
function artwork(a,label){const url=assetSource(a);if(!url)return `<span class="asset"><span class="asset-placeholder"><b>${esc(label)}</b><span>${T('imageOff')}</span></span></span>`;return `<span class="asset" data-asset="${esc(a.assetId)}" role="button" tabindex="0" aria-label="${esc(label)}"><img src="${esc(url)}" alt="${esc(label)}" loading="lazy" decoding="async" referrerpolicy="no-referrer"><span class="asset-status">${T('imageLoading')}</span></span>`}
function hookImages(){$$('.asset img').forEach(im=>{const ok=()=>{im.parentElement.querySelector('.asset-status').textContent=T('imageAvailable')};const fail=()=>{im.hidden=true;im.parentElement.querySelector('.asset-status').textContent=T('imageFailed')};im.addEventListener('load',ok,{once:true});im.addEventListener('error',fail,{once:true});if(im.complete)(im.naturalWidth?ok:fail)()})}
function caseStatus(c){return T(c._contentLevel==='full'?'fullRecord':readable(c)?'excerpt':'directoryOnly')}
function caseTiles(cases){return `<div class="casegrid">${cases.map(c=>`<button class="casecard" data-action="case" data-case="${esc(c.caseId)}" aria-pressed="${state.caseId===c.caseId}">${artwork(assetFor(c.caseId),caseTitle(c))}<span class="casebody"><strong>${esc(caseTitle(c))}</strong><small>${esc(text(c.region?.label))}</small><small>${esc(span(c))}</small><span class="pilltag">${caseStatus(c)}</span><small>${pair('历史参考：','Historical reference: ')}${esc(vtext(FIELDS[topic().fields[0]]))} · ${pair('以原记录字段为阅读线索，不代表当前事实。','A reading lead from the recorded field, not a current fact.')}</small></span></button>`).join('')}</div>`}
function sourceCase(c){let n=Array.isArray(c.evidence)?c.evidence.length:0;return `<details class="sourcesdetails"><summary>${T('sourceRange')}</summary><p>${T('recordNotFact')}</p><p>${T(n?'referencesPresent':'externalEmpty')}</p>${sourceLink(PATH.cases,T('recordSource'))} · ${sourceLink(PATH.assets,T('assetSource'))}${c._depthSource?' · '+sourceLink(c._depthSource,pair('补充字段记录','Supplementary field records')):''}<p>${esc(c.caseId)} · ${SHA.slice(0,8)}${c._localVersionDifferent?' · '+pair('已确认的不同本地版本','Confirmed different local version'):''}</p></details>`}
function historyBrowser(){const regs=[...new Set(db.cases.flatMap(c=>c.region?.regionIds||[]))].sort();let arr=db.cases.filter(c=>{const s=(text(c.title)+' '+text(c.region?.label)+' '+(c.aliases||[]).join(' ')).toLowerCase();let w=c.timeWindow;return !!field(c,topic().fields[0])&&(!state.caseSearch||s.includes(state.caseSearch.toLowerCase()))&&(!state.caseRegion||(c.region?.regionIds||[]).includes(state.caseRegion))&&(!state.casePeriod||c.caseId.startsWith('CA-'+state.casePeriod+'-'))&&(!state.applyYear||(w&&w.startYear<=state.year&&w.endYear>=state.year))});let c=arr.find(c=>c.caseId===state.caseId);
return `<p class="small muted">${T('historicalReading')} · ${db.cases.length} ${pair('个目录条目','catalogue entries')}</p><div class="casetools"><label><span>${T('caseSearch')}</span><input id="caseSearch" type="search" value="${esc(state.caseSearch)}" placeholder="${T('casePlaceholder')}"></label><label><span>${T('region')}</span><select id="caseRegion"><option value="">${T('allAreas')}</option>${regs.map(r=>`<option value="${esc(r)}" ${state.caseRegion===r?'selected':''}>${esc((state.lang==='zh'?REGION_ZH:REGION_EN)[r]||r)}</option>`).join('')}</select></label><label><span>${pair('历史窗口','Historical window')}</span><select id="casePeriod"><option value="">${T('allPeriods')}</option>${db.periods.map(p=>`<option value="${p.periodId}" ${state.casePeriod===p.periodId?'selected':''}>${esc(text(p.title))}</option>`).join('')}</select></label></div><label class="small muted" style="display:block;margin-top:10px"><input type="checkbox" id="applyYear" ${state.applyYear?'checked':''}> ${T('applyYear')} · ${yearText(state.year)}</label><p class="small muted">${T('caseScope')}</p>${arr.length?caseTiles(arr.slice(0,state.caseLimit)):`<p class="empty">${T('noMatches')}</p>`}${arr.length>state.caseLimit?button('moreCases',T('more')):''}${c?caseMain(c):''}`}
function caseMain(c){const fields=topic().fields;return `<section class="section divider" id="caseReading"><div class="sectiontop"><div><div class="eyebrow">${T('cases')}</div><h2>${esc(caseTitle(c))}</h2><div class="small muted">${esc(span(c))} · ${esc(text(c.region?.label))}</div></div><div class="actions">${button('compareCase',T('compareCases'),`data-case="${c.caseId}"`)}${button('pane',T('lifeAction'),'data-pane="life"')}</div></div><div class="casemain"><div class="stage">${artwork(assetFor(c.caseId,selectedImageRole),caseTitle(c))}<div class="storystrip"><div class="subnav">${['CASE_HERO','CASE_SECONDARY'].map(r=>button('imageRole',T(r==='CASE_HERO'?'primaryImage':'secondaryImage'),`data-role="${r}" aria-pressed="${r===selectedImageRole}"`)).join('')}</div><p class="small muted compact">${T('imageCaption')}</p></div></div><section class="panel"><span class="pilltag">${caseStatus(c)}</span><h3 style="margin-top:12px">${esc(vtext(topic().question))}</h3>${fields.map(k=>`<h3 style="font-size:15px;margin-top:20px">${esc(vtext(FIELDS[k]))}</h3><p>${esc(field(c,k)||T('fieldMissing'))}</p>`).join('')}</section></div><details class="sourcesdetails casebody-panel"><summary>${T('readRemaining')}</summary><div class="fieldgrid">${Object.entries(FIELDS).filter(([k])=>!fields.includes(k)).map(([k,l])=>`<article><h3>${esc(vtext(l))}</h3><p>${esc(field(c,k)||T('fieldMissing'))}</p></article>`).join('')}</div></details>${sourceCase(c)}<div class="section">${figureButtons(topic().figs)}</div></section>`}
function historySnapshots(){let s=db.snapshots.find(s=>s.snapshotId===state.snapshot);return `<div class="note">${T('historicalReading')} · ${T('mapCaveat')}</div><div class="timeline">${db.snapshots.map(s=>`<button data-action="snapshot" data-id="${s.snapshotId}" aria-pressed="${state.snapshot===s.snapshotId}"><strong>${esc(yearText(s.year))}</strong><small>${esc(text(s.title))}</small></button>`).join('')}</div>${s?snapshotMain(s):`<p class="empty">${T('noSnapshot')}</p>`}`}
function snapshotMain(s){let a=db.assets.find(a=>a.assetId===s.posterAssetRef||a.assetId===s.visualAssetId||(a.subjectId===s.snapshotId&&['WORLD_SNAPSHOT_ATMOSPHERE','WORLD_RECONFIGURATION_SNAPSHOT'].includes(a.family))),linked=(s.majorCaseIds||s.representativeObjects?.map(r=>r.caseId)||[]).map(caseById).filter(Boolean);return `<div class="sectiontop"><h2>${esc(text(s.title))}</h2><span class="pilltag">${T('historicalReading')}</span></div><div class="casemain"><div class="stage">${artwork(a,text(s.title))}<div class="mapcaption">${T('imageCaption')}</div></div><section class="panel"><h3>${yearText(s.year)}</h3><p>${esc(text(s.summary)||T('snapshotEmpty'))}</p>${sourceLink((s._book===6?PATH.reconfigurationSnapshots:PATH.snapshots),T('sourceRecord'))}<p class="small muted">${T('recordNotFact')}</p></section></div>${caseTiles(linked)}<div class="section">${figureButtons(s._book===6?['13A','13C','13D']:['12A','12C','12D'])}</div>`}
function compareCaseView(){let a=caseById(state.caseId),b=caseById(state.caseRight);let options=id=>db.cases.map(c=>`<option value="${c.caseId}" ${id===c.caseId?'selected':''}>${esc(caseTitle(c))}</option>`).join('');if(!a||!b)return `<p class="empty">${T('noMatches')}</p>`;let wa=a.timeWindow,wb=b.timeWindow,overlap=wa&&wb&&Math.max(wa.startYear,wb.startYear)<=Math.min(wa.endYear,wb.endYear);return `<div class="duo"><label>${T('left')}<select id="compareCaseLeft" style="width:100%;padding:10px">${options(state.caseId)}</select></label><label>${T('right')}<select id="compareCaseRight" style="width:100%;padding:10px">${options(state.caseRight)}</select></label></div><p class="note">${T(overlap?'overlap':'nonOverlap')}</p>${a.caseId===b.caseId?`<p class="note">${T('sameCase')}</p>`:''}<div class="duo">${[a,b].map(c=>`<div class="stage">${artwork(assetFor(c.caseId),caseTitle(c))}<div class="storystrip"><h3>${esc(caseTitle(c))}</h3><p class="small muted">${esc(span(c))}</p>${button('case',T('openCase'),`data-case="${c.caseId}"`)}</div></div>`).join('')}</div>${topicBar()}<div class="table-scroll"><table class="comparison-table"><thead><tr><th>${T('topic')}</th><th>${esc(caseTitle(a))}</th><th>${esc(caseTitle(b))}</th></tr></thead><tbody>${topic().fields.map(k=>`<tr><th scope="row">${esc(vtext(FIELDS[k]))}</th><td>${esc(field(a,k)||T('fieldMissing'))}</td><td>${esc(field(b,k)||T('fieldMissing'))}</td></tr>`).join('')}</tbody></table></div>${sourceCase(a)}${sourceCase(b)}<div class="section">${figureButtons(['12D',...topic().figs.slice(0,2)])}</div>`}
function renderBooks(){$('#bookIndex').innerHTML=VOL.map(b=>`<button class="bookcard" data-action="book" data-book="${b.n}" aria-pressed="${state.book===b.n}"><span class="roman">${['I','II','III','IV','V','VI'][b.n-1]}</span><span><strong>${esc(vtext(b.ux))}</strong><small>${esc(vtext(b.desc))}</small></span></button>`).join('');$('#bookDetail').hidden=!state.book;if(state.book){let b=VOL.find(b=>b.n===state.book),ids=Object.keys(FIGURES).filter(k=>FIGURES[k].volume===b.n);$('#bookDetail').innerHTML=`<div class="eyebrow">${T('book').replace('{n}',b.n)}</div><h2>${esc(vtext(b.ux))}</h2><p>${esc(vtext(b.desc))}</p><p class="small muted">${esc(vtext(b.title))} · ${b.parts.map(p=>T('part').replace('{n}',p)).join(' / ')}</p>${b.n===1?`<div class="note">${T('methodNotImported')}</div><div class="actions">${siteLink('/perspectives/phi-configuration/',T('methodEntry'))}${button('fromMethod',T('methodDirection'))}${siteLink('/perspectives/profile/',T('profileEntry'))}</div>`:`<div class="actions">${button('bookTopic',vtext(TOPICS[b.topic].question),`data-topic="${b.topic}"`,'primary')}${button('bookFigures',T('viewFigures'),`data-book="${b.n}"`)}</div><p class="small muted compact">${T('chapterGap')}</p>`}<div class="actions">${siteLink(bookRoute(b.n),T('bookLink'))}</div>${ids.length?`<div class="fig-grid">${ids.map(id=>figButton(id)).join('')}</div>`:''}`}}
function figButton(id){let f=FIGURES[id];return `<button class="fig-button" data-action="figure" data-id="${id}" aria-pressed="${state.fig===id}"><small>${T('book').replace('{n}',f.volume)} · ${id}</small><strong>${esc(figureLabel(id))}</strong></button>`}
function atlasView(){let ids=state.book&&state.book>1?Object.keys(FIGURES).filter(k=>FIGURES[k].volume===state.book):Object.keys(FIGURES);return `<div class="sectiontop"><div><h2>${T('atlas')}</h2><p class="small muted">${T('bookSummary')} · ${T('chapterGap')}</p></div><div class="actions">${button('allFigures',pair('全部原有图解','All retained figures'))}</div></div><div class="fig-grid">${ids.map(figButton).join('')}</div>${figureDetail(state.fig)}`}
function figureDetail(id){const f=FIGURES[id];if(!f)return '';let panel;if(id==='13H'){panel=`<p class="note">${T('matrixNote')}</p><table class="matrix"><thead><tr><th>${pair('现实语法','Reality grammar')}</th>${['formation','runtime','continuity'].map(k=>`<th>${T(k)}</th>`).join('')}</tr></thead><tbody>${GRAMMAR.map((g,i)=>`<tr><td class="rowname">${esc(vtext(g))}</td>${[0,1,2].map(j=>{let n=i+1+j*16;return `<td><button data-action="cell" data-cell="${n}" aria-pressed="${state.cell===n}">${String(n).padStart(2,'0')}${[8,16,24,32,40,48].includes(n)?' ◇':''}</button></td>`}).join('')}</tr>`).join('')}</tbody></table><div class="model-detail">${state.cell?`${String(state.cell).padStart(2,'0')} · ${esc(vtext(GRAMMAR[(state.cell-1)%16]))} · ${T(['formation','runtime','continuity'][Math.floor((state.cell-1)/16)])}<br>`:''}${T('cellNote')}</div>`}
else if(id==='13I')panel=scenarios();else if(id==='13F')panel=`<p class="note">${T('lifeIntro')}</p><div class="concept-grid">${Object.entries(LIFE).filter(([k])=>topic().life.slice(0,3).includes(k)).map(([k,l])=>button('lifeFocus',vtext(l),`data-focus="${k}"`)).join('')}</div>`;else if(id==='13G')panel=`<div class="concept-grid">${[['资源余量','Resource margin'],['转换成本','Transition cost'],['恢复能力','Recovery capacity']].map(l=>button('me',vtext(l))).join('')}</div><p class="small muted">${T('noModelScores')}</p>`;
else{let refs=id.startsWith('12')?[['形成条件','Conditions of formation'],['不同路径','Different pathways'],['比较范围与来源','Comparison scope and sources']]:id.startsWith('8')||id.startsWith('9')?[['承担与维护','Responsibility and maintenance'],['协商与边界','Coordination and boundaries'],['变化后的结果','Outcomes after change']]:id.startsWith('10')||id.startsWith('11')?[['能力与连接','Capability and connections'],['长期成本与依赖','Long-term costs and dependencies'],['延续与承接','Continuity and handoff']]:[['主体与关系','Participants and relationships'],['变化与条件','Change and conditions'],['日常与实际选择','Everyday life and real choices']];panel=`<div class="flow">${refs.map((l,i)=>`${i?'<span class="arrow" aria-hidden="true">→</span>':''}<div class="node">${esc(vtext(l))}</div>`).join('')}</div><p class="small muted">${pair('这是本页的阅读提要，不是新增原著定义，也不表示当前地区已被判定属于某个阶段。','This is an on-page reading guide, not a new canonical definition or an assignment of the selected place to a stage.')}</p>`}
return `<section id="figureDetail" class="figdetail"><div class="eyebrow">${T('book').replace('{n}',f.volume)} · ${T('part').replace('{n}',f.part)} · ${id}</div><h3>${esc(figureLabel(id))}</h3>${panel}<div class="actions">${button('original',T('bookOriginal'),`data-id="${id}"`)}${siteLink(bookRoute(f.volume),T('bookLink'))}</div><p class="small muted compact">${T('originalNote')}</p></section>`}
function scenarios(){let d=DIRECTIONS[state.scenario];return `<p class="note">${T('scenarioNote')}</p><div class="scenarios">${DIRECTIONS.map((d,i)=>`<button data-action="scenario" data-id="${i}" aria-pressed="${state.scenario===i}"><strong>${esc(d[state.lang==='zh'?0:1])}</strong><small>${esc(d[state.lang==='zh'?2:3])}</small></button>`).join('')}</div><section class="model-detail"><h3>${esc(d[state.lang==='zh'?0:1])}</h3><p><b>${T('requirements')}：</b>${T('scenarioRequirements')}</p><p><b>${T('counterEvidence')}：</b>${T('scenarioCounter')}</p><p class="small muted">${T('noModelScores')}</p></section>`}
const LIFE_CHECKS={environment:['核对供水范围、环境观测地点与暴露时间；不能用全国背景推断住处状况。','Check service areas, monitoring locations and exposure dates; national background cannot establish home conditions.'],time:['核对通勤、等待、中断与替代安排的实际耗时；不从地图推定个人时间压力。','Check actual travel, waiting, disruption and alternative arrangements; the map cannot establish personal time pressure.'],safety:['核对事件地点、时期、发生频率及防护安排；历史案例不是当前风险概率。','Check event locations, periods, frequency and protective measures; historical cases are not current risk probabilities.'],learning:['核对教育、培训、交通与参与条件；联系增加并不自动带来可用机会。','Check education, training, transport and access conditions; more connections do not automatically create usable opportunities.'],housing:['核对住房成本、空间、服务及具体地点；地区平均值不等于个人居住条件。','Check housing costs, space, services and location; regional averages are not personal housing conditions.'],future:['核对已有承诺、资源期限与可调整选择；这些问题不是预测。','Check existing commitments, resource horizons and adjustable choices; these questions are not predictions.']};
function lifeView(){if(!topic().life.includes(state.lifeFocus))state.lifeFocus=topic().life[0];let focus=LIFE[state.lifeFocus]||LIFE.time;return `<div class="sectiontop"><div><h2>${T('lifeTitle')}</h2><p class="small muted">${T('lifeIntro')}</p></div></div><div class="flow">${topic().steps.map((s,i)=>`${i?'<span class="arrow" aria-hidden="true">→</span>':''}<div class="node">${esc(vtext(s))}</div>`).join('')}</div><div class="concept-grid">${Object.entries(LIFE).filter(([k])=>topic().life.slice(0,3).includes(k)).map(([k,l])=>`<button data-action="lifeFocus" data-focus="${k}" aria-pressed="${state.lifeFocus===k}">${esc(vtext(l))}</button>`).join('')}</div><section class="panel"><h3>${esc(vtext(focus))}</h3><p>${esc(vtext(topic().qs[0]))}</p><p>${LIFE_CHECKS[state.lifeFocus]?vtext(LIFE_CHECKS[state.lifeFocus]):state.lifeFocus==='cost'?pair('核对账单、价格日期、补贴与替代选择；尚无本地区费用变化资料。','Check bills, price dates, subsidies and alternatives; local cost changes are not established.'):state.lifeFocus==='work'?pair('核对行业、能源使用、工作安排与雇佣记录；尚无本地区就业影响证据。','Check industry, energy use, working arrangements and employment records; local employment effects are not established.'):pair('核对与这个生活方向相关的实际记录、日期及适用范围；尚无足以确认个人影响的资料。','Check records, dates and scope for this life direction; personal effects are not established.')}</p><p>${pair('哪些费用、时间和责任有真实记录？影响是否实际发生，是否存在替代与例外？','Which costs, time demands and responsibilities are documented? Has the effect occurred, and are alternatives or exceptions available?')}</p><span class="pilltag">${T('sourceNotReady')}</span></section><div class="section actions">${button('me',T('addPersonal'),'','primary')}${button('pane',T('ask'),'data-pane="ask"')}${button('figure',figureLabel('13F'),'data-id="13F"')}${button('figure',figureLabel('13G'),'data-id="13G"')}</div>`}
function askView(){return `<section class="panel"><div class="eyebrow">${T('ask')}</div><h2>${T('askTitle')}</h2><p>${T('askNote')}</p><label for="askQuestion">${T('askInput')}</label><textarea id="askQuestion" maxlength="2000" style="display:block;width:100%;min-height:110px;padding:14px;margin:10px 0">${esc(askQuestion||q())}</textarea><div class="actions">${button('askLocal',T('search'))}${button('copyAsk',T('askCopy'))}${button('handoffAsk',T('askOpen'))}</div><p class="small muted compact">${T('askNoAuto')}</p><div class="note">${T('askDisabled')}</div></section><section class="section"><h3>${pair('与当前主题相连的书图','Book figures related to this topic')}</h3>${figureButtons(topic().figs)}</section>`}
function renderExplore(){let menus=state.mode==='current'?[['map','map'],['data','data'],['life','life'],['ask','ask']]:state.mode==='history'?[['cases','cases'],['timeline','timeline'],['atlas','atlas'],['ask','ask']]:[['places','comparePlaces'],['casecompare','compareCases'],['conditions','conditions'],['ask','ask']];if(!menus.some(m=>m[0]===state.pane))state.pane=menus[0][0];let body=state.pane==='map'?mapHTML():state.pane==='data'?dataView():state.pane==='places'?dataView(true):state.pane==='cases'?historyBrowser():state.pane==='timeline'?historySnapshots():state.pane==='casecompare'?compareCaseView():state.pane==='atlas'?atlasView():state.pane==='life'?lifeView():state.pane==='conditions'?`${scenarios()}${figureButtons(['13H','13I','13G'])}`:askView();$('#exploreView').innerHTML=`<div class="sectiontop"><div><span class="eyebrow">${esc(nameGeo(state.region))} · ${esc(vtext(topic().name))}</span></div>${subNav(menus)}</div>${state.pane==='map'?`<section class="panel topic-coverage"><h3>${pair('事实资料与尚缺资料','Facts and coverage gaps')}</h3><p>${pair('本页可按指定年份查询人口与 GDP，作为地区背景。当前主题的地区指标尚未接入；下方解释阅读和历史参考不能证明当代地区状况。','Population and GDP can be queried for an exact year as regional background. Regional indicators for this topic are not connected; explanation reading and historical references do not establish current local conditions.')}</p>${button('pane',pair('查看地区背景','View regional background'),'data-pane="data"')}</section>`:''}${body}${customQuestion||evidenceIntent?'':worldGuideLinks(getLocale())}${sourceReadings(topic().book)}`;applyMapTransform();hookImages();}
function statsText(){return pair(`${db.cases.length} 个案例目录；${db.cases.filter(readable).length} 个案例有已读文字；${db.assets.length} 条旧图片记录；${localImages.size+db.assets.filter(a=>a._embeddedImage).length} 张核验后本地原图。`,`${db.cases.length} catalogue cases; ${db.cases.filter(readable).length} cases with loaded text; ${db.assets.length} existing image records; ${localImages.size+db.assets.filter(a=>a._embeddedImage).length} verified local images.`)}
function showSources(){openModal(T('sourceTitle'),`<p>${T('sourceIntro')}</p><section class="sourceentry"><h3>${T('contentState')}</h3><p>${esc(statsText())}</p><p>${pair('392 是继承的历史清单条目数，不是当前 R2 总数、可用图片数或页面使用率。','392 is the inherited historical inventory count, not the current R2 total, successful-image count or page utilization.')}</p>${sourceLink(PATH.cases,T('recordSource'))} · ${sourceLink(PATH.assets,T('assetSource'))}</section><section class="sourceentry"><h3>${T('sourceGeometry')}</h3><p>${T('sourceGeometryNote')}</p>${external('https://www.naturalearthdata.com/about/terms-of-use/',pair('自然地理底图使用说明','Natural Earth terms of use'))}</section><section class="sourceentry"><h3>${T('sourceBooks')}</h3><p>${T('sourceBooksNote')}</p>${sourceLink('content/registry/successors/eight-volume-v1/books.json',pair('八册正式登记','Formal eight-volume registry'))}<div class="actions" style="margin-top:12px">${siteLink('/books/reality-observation/',T('sourceBook7'))}${siteLink('/books/reality-navigation/',T('sourceBook8'))}</div></section><section class="sourceentry"><h3>${T('sourceOriginals')}</h3><p>${T('sourceOriginalsNote')}</p></section><section class="sourceentry"><h3>${T('data')}</h3><p>${T('wbScope')}</p><p>${T('wbPrivacy')}</p>${external('https://datahelpdesk.worldbank.org/knowledgebase/articles/889392',pair('世界银行公开指标接口','World Bank Indicators API'))}<p>${pair('本地构建环境未能联网实测；这里不宣称已经取得今日数据。','Live requests could not be verified from the build environment; no claim of current-data acquisition is made here.')}</p></section><section class="sourceentry"><h3>${T('sourceAsk')}</h3><p>${T('sourceAskNote')}</p><p>${T('externalBoundary')}</p></section>${button('downloadReport',T('downloadReport'))}`)}
L.contextChanged=['公共问题已改变。个人文字仍被保留，但尚未确认适用于这个新问题。','The public question has changed. Your personal text is retained but has not been confirmed for this new question.'];L.reconfirm=['确认这些个人输入用于当前问题','Confirm these inputs for this question'];L.localOnly=['只在本页整理 · 不代表已经完成账户交接','Local preparation only · Account handoff has not occurred'];L.saveScope=['导出只包含你确认的内容，不代表这些输入已经核实为事实。','Export includes only the categories you authorize; it does not verify them as facts.'];
let privateBoundContext='';
function contextSignature(){return JSON.stringify([state.region,state.topic,state.year,state.baseline,state.scale,state.perspective,state.caseId,state.caseRight,state.snapshot,customQuestion])}
function privateIsCurrent(){return privateBoundContext===contextSignature()}
function privateInputsHTML(){return `<div class="privateform">${consent.self?`<label class="full">${T('selfLabel')}<textarea id="privateSelf" data-private="self" maxlength="5000" placeholder="${T('selfPlaceholder')}">${esc(privateData.self)}</textarea></label>`:''}${consent.method?`<label>${T('methodLabel')}<textarea data-private="method" maxlength="5000" placeholder="${T('methodPlaceholder')}">${esc(privateData.method)}</textarea></label>`:''}${consent.profile?`<label>${T('profileLabel')}<textarea data-private="profile" maxlength="5000" placeholder="${T('profilePlaceholder')}">${esc(privateData.profile)}</textarea></label>`:''}</div>`}
function privateReviewHTML(){return `<section class="section resultcards"><article class="panel"><span class="pilltag">${T('knownWorld')}</span><h3 style="margin-top:12px">${esc(nameGeo(state.region))} · ${state.year}</h3><p>${esc(vtext(topic().question))}</p>${INDICATORS.some(i=>observations.get(obsKey(state.region,i.id,state.year))?.status==='value')?'':`<p class="small muted">${T('sourceNotReady')}</p>`}${INDICATORS.map(i=>`<h3 style="font-size:14px">${esc(vtext(i.label))}</h3>${obsCell(state.region,i)}`).join('')}</article><article class="panel"><span class="pilltag">${T('myConditions')}</span><p class="privacy-preview" style="margin-top:15px">${esc(consent.self?(privateData.self||T('noPersonal')):T('noPermissions'))}</p></article><article class="panel"><span class="pilltag">${T('methodInterpretation')}</span><p class="privacy-preview" style="margin-top:15px">${esc(consent.method?(privateData.method||T('noPersonal')):T('noPermissions'))}</p><span class="pilltag">${T('profileInterpretation')}</span><p class="privacy-preview" style="margin-top:15px">${esc(consent.profile?(privateData.profile||T('noPersonal')):T('noPermissions'))}</p></article><article class="panel"><span class="pilltag">${T('unknowns')}</span><p style="margin-top:15px">${T('unknownNote')}</p></article></section>`}
function navigationHTML(){const steps=[['goal','navGoal'],['options','navOptions'],['attempt','navTry'],['result','navResult'],['review','navReview']];return `<section class="worksheet"><div class="eyebrow">${T('localOnly')}</div><h2>${T('navTitle')}</h2><p class="small muted">${T('navNote')}</p>${navGranted?`<div class="stepnav">${steps.map(([id,k],i)=>`<button data-action="navStep" data-step="${id}" aria-pressed="${navStep===id}">${i+1}. ${T(k)}</button>`).join('')}</div><label for="navText">${T(steps.find(s=>s[0]===navStep)[1])}</label><textarea id="navText" data-private="${navStep}" maxlength="6000" placeholder="${T('navPh')}" style="display:block;width:100%;min-height:160px;padding:15px;margin:12px 0">${esc(privateData[navStep])}</textarea><div class="actions">${button('handoffNavigation',pair('带到 My Reality 确认','Continue in My Reality'))}${button('reviewPrivateExport',T('savePrivate'),'','primary')}${siteLink('/reality/',pair('打开既有现实与导航入口','Open the existing reality / navigation entry'))}${siteLink('/professional/',pair('查看专业服务','View professional services'))}</div><p class="small muted compact">${T('externalBoundary')}</p>`:`<div class="checks"><label><input type="checkbox" id="navConsent"><span>${T('navConsent')}</span></label></div>${button('startNavigation',T('navStart'))}`}</section>`}
