function revoke(){consent={self:false,method:false,profile:false};consentGranted=false;navGranted=false;privatePreview=false;privateBoundContext='';privateData={self:'',method:'',profile:'',goal:'',options:'',attempt:'',result:'',review:''};reviewExport=null;if($('#modal').open)closeModal();$('#modalBody').replaceChildren();render();toast(T('cleared'))}
