function saveHash(){const vals={wi:evidenceIntent,wq:evidenceQuarter,v:2,lang:state.lang,mode:state.mode,pane:state.pane,region:state.region,topic:state.topic,year:state.year,baseline:state.baseline,scale:state.scale,perspective:state.perspective,case:state.caseId,other:state.caseRight,fig:state.fig,snapshot:state.snapshot,zoom:mapZoom,pan:mapPan,caseRegion:state.caseRegion,casePeriod:state.casePeriod,caseSearch:state.caseSearch,lifeFocus:state.lifeFocus,applyYear:state.applyYear,book:state.book};try{window.history.replaceState(window.history.state,'','#'+new URLSearchParams(vals))}catch{}}
function restore(){const p=new URLSearchParams(location.hash.slice(1));const nextIntent=p.get('wi')||'';customQuestion='';searchText='';searchResults=null;evidenceIntent=WORLD_ANSWER_INTENTS.includes(nextIntent)?nextIntent:'';evidenceQuarter=p.get('wq')==='Q3'?'Q3':'';let ctx=SEED.reviewContext||{};Object.keys(ctx).forEach(k=>{if(['lang','mode','pane','region','topic','year','baseline','scale','perspective','caseId','caseRight','fig','snapshot'].includes(k))state[k]=ctx[k]});mapZoom=Math.min(6,Math.max(1,Number(p.get('zoom'))||1));mapPan=Math.min(3000,Math.max(-3000,Number(p.get('pan'))||0));state.applyYear=p.get('applyYear')==='true';state.book=Math.min(6,Math.max(0,Number(p.get('book'))||0));for(const k of ['caseRegion','casePeriod','caseSearch','lifeFocus'])if(p.has(k))state[k]=p.get(k);const keys={lang:'lang',mode:'mode',pane:'pane',region:'region',topic:'topic',baseline:'baseline',scale:'scale',perspective:'perspective',case:'caseId',other:'caseRight',fig:'fig',snapshot:'snapshot'};for(const [k,s]of Object.entries(keys))if(p.has(k))state[s]=p.get(k);if(p.has('year'))state.year=Number(p.get('year'));if(!['zh','en'].includes(state.lang))state.lang='zh';if(!['current','history','compare'].includes(state.mode))state.mode='current';if(state.region!=='GLOBAL'&&!country(state.region))state.region='GLOBAL';if(!country(state.baseline))state.baseline='IDN';if(!TOPICS[state.topic])state.topic='connections';if(!Number.isInteger(state.year)||state.year<-12000||state.year>2100||state.year===0)state.year=2026;if(!['place','city','network'].includes(state.scale))state.scale='place';if(!['general','worker','caregiver','business','student'].includes(state.perspective))state.perspective='general';if(!caseById(state.caseId))state.caseId='CA-T11-02';if(!caseById(state.caseRight))state.caseRight='CA-T06-02';if(!FIGURES[state.fig])state.fig='13F';if(!db.snapshots.some(s=>s.snapshotId===state.snapshot))state.snapshot=db.snapshots[0]?.snapshotId||'';}
function doSearch(){searchText=$('#globalSearch').value.trim();if(!searchText){toast(T('searchEmpty'));return}const lower=searchText.toLowerCase();const geos=GEO.filter(g=>Object.values(g.name).some(t=>t.toLowerCase().includes(lower))||g.id.toLowerCase()===lower).slice(0,8),cases=db.cases.filter(c=>[c.title?.en,c.title?.['zh-Hans'],c.region?.label?.en,c.region?.label?.['zh-Hans'],...(c.aliases||[])].some(s=>typeof s==='string'&&s.toLowerCase().includes(lower))).slice(0,12);const topics=Object.entries(TOPICS).filter(([k,t])=>t.name.some(n=>n.toLowerCase().includes(lower))||t.keywords.split(' ').some(w=>w.length>1&&lower.includes(w.toLowerCase())));const figs=Object.keys(FIGURES).filter(id=>id.toLowerCase()===lower||Object.values(FIGURES[id].label).some(s=>s.toLowerCase().includes(lower))).slice(0,8);const readings=SEED.readings.filter(r=>r.locales?.[state.lang==='zh'?'zh-Hans':'en']&&[r.title?.[state.lang==='zh'?'zh-Hans':'en'],r.summary?.[state.lang==='zh'?'zh-Hans':'en']].some(t=>t?.toLowerCase().includes(lower))).slice(0,8);searchResults={readings:readings.map(r=>r.id),geos:geos.map(g=>g.id),cases:cases.map(c=>c.caseId),topics:topics.map(([k])=>k),figs};customQuestion=searchText;const evidencePlan=worldQuestionPlan(searchText,{region:state.region,year:state.year});evidenceIntent=evidencePlan.intent;evidenceQuarter=evidencePlan.requests.some(r=>r.period.endsWith('-Q3'))?'Q3':'';if(country(evidencePlan.scope.region))state.region=evidencePlan.scope.region;const evidenceYear=Number(evidencePlan.scope.period.slice(0,4));if(Number.isInteger(evidenceYear))state.year=evidenceYear;history.pushState(history.state,'',location.href);if(topics.length===1)state.topic=topics[0][0];render();(evidenceIntent?answerHost:$('#searchResults')).scrollIntoView({behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'start'})}
function renderSearchResults(){const el=$('#searchResults');el.hidden=!searchResults;if(!searchResults)return;const has=Object.values(searchResults).some(x=>x.length);el.innerHTML=`<p class="small muted">${T('searchNoAnswer')}</p><div class="actions">${(searchResults.readings||[]).map(id=>{const r=SEED.readings.find(r=>r.id===id);const u=new URL(r.href,location.origin);u.searchParams.set('locale',getLocale());u.hash=location.hash;return `<a class="source-reading-link" href="${esc(u.pathname+u.search+u.hash)}">${esc(r.title[getLocale()])}</a>`}).join('')}${searchResults.geos.map(id=>button('searchRegion',nameGeo(id),`data-id="${id}"`)).join('')}${searchResults.topics.map(id=>button('topic',vtext(TOPICS[id].name),`data-topic="${id}"`)).join('')}${searchResults.cases.map(id=>button('case',caseTitle(caseById(id)),`data-case="${id}"`)).join('')}${searchResults.figs.map(id=>button('figure',figureLabel(id),`data-id="${id}"`)).join('')}</div>${has?'':`<p>${T('noMatches')}</p>`}${button('closeSearch',T('close'))}`}
async function readPublicData(both=false){
 if(readBusy)return;const ids=[state.region,...(both?[state.baseline]:[])];
 if(ids.some(id=>!country(id)?.iso2)){toast(T('choosePlace'));return}
 if(state.year<1960||state.year>new Date().getUTCFullYear()){toast(T('unsupportedYear'));return}
 const sequence=++dataRequestSequence;const year=state.year,requestContext=[state.region,state.topic,state.year,state.baseline].join('|');readBusy=true;dataRequestState=T('readingData');render();let success=0,missing=0,failed=0;
 for(const id of [...new Set(ids)])for(const i of INDICATORS){try{
 const params=new URLSearchParams({country:country(id).iso2,indicator:i.id,year:String(year)});
 const r=await fetch('/api/world-observations?'+params,{credentials:'omit'});if(sequence!==dataRequestSequence)return;if(!r.ok)throw Error('SERVICE_ERROR');const b=await r.json(),o=b.observation;
 if(!o||o.country!==country(id).iso2||o.indicator!==i.id||o.year!==year)throw Error('IDENTITY_MISMATCH');
 const status=o.state==='OBSERVED'?'value':o.state==='YEAR_MISSING'?'missing':'error';
 observations.set(obsKey(id,i.id,year),{...o,status,region:id,indicator:i.id,url:o.sourceUrl,lastupdated:o.datasetUpdatedAt||null});
 status==='value'?success++:status==='missing'?missing++:failed++;
 }catch{if(sequence!==dataRequestSequence)return;observations.set(obsKey(id,i.id,year),{status:'error',state:'SERVICE_ERROR',year,region:id,indicator:i.id});failed++;}}
 readBusy=false;if(requestContext!==[state.region,state.topic,state.year,state.baseline].join('|')){dataRequestState='';render();return;}dataRequestState=pair(`已读取 ${success} 项；${missing} 项该年空缺；${failed} 项请求失败。年份：${year}。`,`Read ${success} values; ${missing} missing for that year; ${failed} failed. Year: ${year}.`);render();
}
function openModal(title,html){$('#modalTitle').textContent=title;$('#modalBody').innerHTML=html;if(!$('#modal').open)$('#modal').showModal();$('#modalBody').scrollTop=0;}
function closeModal(){$('#modal').close();$('#modalBody').replaceChildren();reviewExport=null;if(activeRead?.isConnected)activeRead.focus();activeRead=null;}
async function copyText(s){try{await navigator.clipboard.writeText(s);toast(T('copied'))}catch{openModal(T('copy'),`<p>${T('copyFallback')}</p><textarea readonly style="width:100%;min-height:300px;padding:15px">${esc(s)}</textarea>`)}}
function download(name,content,mime='application/json'){const b=new Blob([content],{type:mime}),url=URL.createObjectURL(b),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),2000)}
const EXPECTED_CASES=new Set(SEED.cases.map(c=>c.caseId));
const DEEP_FIELDS=new Set(['populationBase','settlementPattern','resourceBase','beliefSystem','technology','militaryStructure','civilizationDensity','capacity','load','alignment','expansionPattern']);
const hex=b=>[...new Uint8Array(b)].map(x=>x.toString(16).padStart(2,'0')).join('');
async function digest(b,algo='SHA-256'){if(!crypto?.subtle)throw Error(pair('当前浏览器不支持文件校验，请用桌面浏览器。','File hashing is not supported here. Use a desktop browser.'));return hex(await crypto.subtle.digest(algo,b));}
async function gitBlob(bytes){const pre=new TextEncoder().encode('blob '+bytes.byteLength+'\0'),a=new Uint8Array(pre.length+bytes.byteLength);a.set(pre);a.set(new Uint8Array(bytes),pre.length);return digest(a,'SHA-1')}
function rejectUnsafe(x,depth=0){if(depth>60)throw Error('JSON depth');if(!x||typeof x!=='object')return;for(const k of Object.keys(x)){if(['__proto__','constructor','prototype'].includes(k))throw Error('Unsafe JSON key');rejectUnsafe(x[k],depth+1)}}
function parseBytes(b){if(b.byteLength>12*1024*1024)throw Error('File size');const d=JSON.parse(new TextDecoder('utf-8',{fatal:true}).decode(b).replace(/^\uFEFF/,''));rejectUnsafe(d);return d}
function rows(d,k){if(!d||!Array.isArray(d[k])||!d[k].every(x=>x&&typeof x==='object'&&!Array.isArray(x)))throw Error('Record structure: '+k);return d[k]}
function unique(arr,k){let ids=new Set();for(const x of arr){if(typeof x[k]!=='string'||!x[k]||ids.has(x[k]))throw Error('Duplicate identity: '+k);ids.add(x[k])}return ids}
async function checkBytes(path,b){let sha256=await digest(b),blob=await gitBlob(b),match=PINNED[path]===blob,normalization=null;if(!match){let s=new TextDecoder().decode(b);if(s.includes('\r\n')){let normalized=new TextEncoder().encode(s.replaceAll('\r\n','\n'));if(await gitBlob(normalized)===PINNED[path]){match=true;normalization='CRLF_TO_LF_FOR_COMPARISON_ONLY'}}}return {path,sha256,gitBlob:blob,versionMatch:match,normalization,bytes:b.byteLength};}
function stage(docs){for(const k of Object.keys(docs)){if(!SOURCE_PATHS.includes(k))throw Error('Unexpected file');rejectUnsafe(docs[k])}if(SOURCE_PATHS.some(p=>!docs[p]))throw Error(pair('需要完整的13份公共图谱文件。','All 13 listed public atlas files are required.'));const base=rows(docs[PATH.cases],'cases'),ids=unique(base,'caseId');if(ids.size!==EXPECTED_CASES.size||[...ids].some(id=>!EXPECTED_CASES.has(id)))throw Error(pair('案例身份与既有目录不一致。','Case identities differ from the retained catalogue.'));const overlays=new Map();for(const p of DEPTH){for(const r of rows(docs[p],'records')){if(!ids.has(r.caseId)||overlays.has(r.caseId)||Object.keys(r).some(k=>k!=='caseId'&&!DEEP_FIELDS.has(k)))throw Error('Depth ownership');overlays.set(r.caseId,{path:p,row:r})}}const cases=base.map(c=>{const o=overlays.get(c.caseId);let row={...c,...(o?.row||{}),_contentLevel:'full'};if(o)row._depthSource=o.path;return row});let as=rows(docs[PATH.assets],'assets');unique(as,'assetId');const amap=new Map(db.assets.map(a=>[a.assetId,{...a}]));for(const a of as){if(!registeredURL(a))throw Error('Invalid image path');const safe=Object.fromEntries(Object.entries(a).filter(([k])=>!k.startsWith('_')));const old=amap.get(a.assetId);if(old?._embeddedImage&&old.sha256===safe.sha256)safe._embeddedImage=old._embeddedImage;amap.set(a.assetId,safe)}const snaps=rows(docs[PATH.snapshots],'snapshots').map(s=>({...s,_metadataOnly:false}));unique(snaps,'snapshotId');for(const s of rows(docs[PATH.reconfigurationSnapshots],'snapshots'))snaps.push({...s,snapshotId:s.id,title:{'zh-Hans':s.metadata?.titleZh||'',en:s.metadata?.titleEn||''},_book:6,_metadataOnly:false});unique(snaps,'snapshotId');return {cases,assets:[...amap.values()],snapshots:snaps.sort((a,b)=>a.year-b.year),periods:rows(docs[PATH.periods],'periods'),comparison:rows(docs[PATH.comparison],'families'),transitions:rows(docs[PATH.transitions],'transitionWindows'),trajectories:rows(docs[PATH.trajectories],'trajectories')};}
function commitStage(candidate,docs,checks,different=false){db=candidate;for(const c of db.cases)c._localVersionDifferent=different;loadedDocuments.clear();for(const [p,d]of Object.entries(docs))loadedDocuments.set(p,d);for(const [id,v]of localImages){let a=db.assets.find(a=>a.assetId===id);if(!a||a.sha256!==v.sha256){URL.revokeObjectURL(v.url);localImages.delete(id)}}importReport={files:checks,cases:db.cases.length,readable:db.cases.filter(readable).length,assets:db.assets.length,differentVersion:different,loadedAt:new Date().toISOString()};pending=null;$('#pendingVersion').hidden=true;remoteImages=false;render();$('#importStatus').textContent=T('importOK');}
async function processDocs(docs,checks){let next=stage(docs),diff=checks.some(c=>!c.versionMatch);if(diff){pending={next,docs,checks};$('#pendingVersion').hidden=false;$('#importStatus').textContent=T('versionChanged')}else commitStage(next,docs,checks)}
function fileIndex(files){const index=new Map();for(const f of files)index.set((f.webkitRelativePath||f.name).replaceAll('\\','/'),f);return index}
function findFile(index,key,basename=false){let matches=[...index].filter(([p])=>p===key||p.endsWith('/'+key)).map(x=>x[1]);if(!matches.length&&basename)matches=[...index.values()].filter(f=>f.name===key.split('/').pop());if(matches.length>1)throw Error('Ambiguous matching file');return matches[0]||null}
async function importRepo(files){if(controlsBusy){toast(T('busy'));return}controlsBusy=true;try{let docs={},checks=[],index=fileIndex(files);for(const p of SOURCE_PATHS){const f=findFile(index,p);if(!f)throw Error(pair('缺少所列公共文件：','Missing listed public file: ')+p);if(f.size>12*1024*1024)throw Error('File size');const b=await f.arrayBuffer();docs[p]=parseBytes(b);checks.push(await checkBytes(p,b));$('#importStatus').textContent=pair(`正在核对 ${checks.length} / 13 份资料…`,`Checking ${checks.length} / 13 files…`)}await processDocs(docs,checks)}catch(e){$('#importStatus').textContent=T('importFail');console.warn('Import validation:',e.message)}finally{controlsBusy=false}}
async function importBundle(file){if(controlsBusy||!file)return;controlsBusy=true;try{if(file.size>48*1024*1024)throw Error('Bundle size');let b=JSON.parse(await file.text());rejectUnsafe(b);if(b.kind!=='PHIOS_WORLD_READER_PUBLIC_BUNDLE')throw Error(pair('不是既有公共图谱资料包。','Not an existing public atlas bundle.'));const docs={},checks=[];for(const p of SOURCE_PATHS){if(b.rawDocuments?.[p]){let bytes=unbase64(b.rawDocuments[p]);docs[p]=parseBytes(bytes);let c=await checkBytes(p,bytes);if(b.sourceManifest?.[p]?.sha256&&b.sourceManifest[p].sha256!==c.sha256)throw Error('Manifest hash mismatch');checks.push(c)}else if(b.documents?.[p]){docs[p]=b.documents[p];checks.push({path:p,versionMatch:false,rawBytesUnavailable:true})}}await processDocs(docs,checks)}catch(e){$('#importStatus').textContent=T('importFail');console.warn('Import validation:',e.message)}finally{controlsBusy=false}}
async function fetchPinned(path){const urls=[RAW+path,'https://api.github.com/repos/getphioscs-UX/phios/contents/'+path+'?ref='+SHA];let last;for(let i=0;i<urls.length;i++){let ctl=new AbortController(),timer=setTimeout(()=>ctl.abort(),10000);try{let r=await fetch(urls[i],{signal:ctl.signal,credentials:'omit',referrerPolicy:'no-referrer'});if(!r.ok)throw Error('HTTP '+r.status);let raw=await r.arrayBuffer();if(i){const encoded=parseBytes(raw);if(encoded.encoding!=='base64')throw Error('Not a full file');raw=unbase64(encoded.content)}let check=await checkBytes(path,raw);if(!check.versionMatch)throw Error('Pinned version differs');return {doc:parseBytes(raw),check}}catch(e){last=e}finally{clearTimeout(timer)}}throw last}
async function networkCatalog(){if(controlsBusy){toast(T('busy'));return}controlsBusy=true;let docs={},checks=[];try{for(const p of SOURCE_PATHS){let x=await fetchPinned(p);docs[p]=x.doc;checks.push(x.check);$('#importStatus').textContent=pair(`正在读取 ${checks.length} / 13 份公开资料…`,`Reading ${checks.length} / 13 public files…`)}await processDocs(docs,checks)}catch{$('#importStatus').textContent=T('networkFail')}finally{controlsBusy=false}}
function mimeOf(b){const a=new Uint8Array(b);if(a.length>12&&String.fromCharCode(...a.slice(0,4))==='RIFF'&&String.fromCharCode(...a.slice(8,12))==='WEBP')return 'image/webp';if(a[0]===137&&a[1]===80&&a[2]===78&&a[3]===71)return 'image/png';if(a[0]===255&&a[1]===216&&a[2]===255)return 'image/jpeg';return null}
async function importImages(files){if(controlsBusy){toast(T('busy'));return}controlsBusy=true;let index=fileIndex(files),counts={verified:0,missing:0,noDigest:0,mismatch:0,ambiguous:0};try{for(const a of db.assets){if(!validKey(a.bucketKey))continue;let f;try{f=findFile(index,a.bucketKey,true)}catch{counts.ambiguous++;continue}if(!f){counts.missing++;continue}if(!/^[a-f0-9]{64}$/i.test(a.sha256||'')){counts.noDigest++;continue}if(f.size>24*1024*1024){counts.mismatch++;continue}const bytes=await f.arrayBuffer(),sha=await digest(bytes),mime=mimeOf(bytes);if(!mime||sha!==a.sha256){counts.mismatch++;continue}const blob=new Blob([bytes],{type:mime});try{let im=await createImageBitmap(blob);if(!im.width||!im.height)throw Error('Empty');im.close()}catch{counts.mismatch++;continue}if(localImages.has(a.assetId))URL.revokeObjectURL(localImages.get(a.assetId).url);localImages.set(a.assetId,{url:URL.createObjectURL(blob),sha256:sha,blob,mime});counts.verified++;}remoteImages=false;render();$('#importStatus').textContent=pair(`已核验 ${counts.verified} 张；缺少摘要 ${counts.noDigest} 张；不符 ${counts.mismatch} 张；同名不明 ${counts.ambiguous} 张。`,`Verified ${counts.verified} images; ${counts.noDigest} lack expected hashes; ${counts.mismatch} mismatches; ${counts.ambiguous} ambiguous filenames.`)}catch{$('#importStatus').textContent=T('importFail')}finally{controlsBusy=false}}
function toBase64(b){let a=new Uint8Array(b),s='';for(let i=0;i<a.length;i+=32768)s+=String.fromCharCode(...a.subarray(i,i+32768));return btoa(s)}
function unbase64(s){if(typeof s!=='string'||!/^[A-Za-z0-9+/=\s]+$/.test(s))throw Error('Base64');return Uint8Array.from(atob(s.replace(/\s/g,'')),c=>c.charCodeAt(0)).buffer}
let baseDocument='';
async function savePublic(){let output={...SEED,...db,reviewContext:publicContext(),autoFetch:false,requestRemoteImages:false,wbObservations:[...observations.values()].filter(o=>['value','missing'].includes(o.status)),sourceManifest:importReport?.files||SEED.sourceManifest},as=db.assets.map(a=>({...a}));let total=0;for(const a of as){let local=localImages.get(a.assetId);if(local&&local.sha256===a.sha256){total+=local.blob.size;if(total>320*1024*1024)throw Error(pair('原图超出单文件导出上限。','Artwork exceeds the single-file export limit.'));a._embeddedImage='data:'+local.mime+';base64,'+toBase64(await local.blob.arrayBuffer())}}output.assets=as;const json=JSON.stringify(output).replaceAll('<','\\u003c');let html=baseDocument.replace(/(<script type="application\/json" id="seed">)[\s\S]*?(<\/script>)/,(_,a,b)=>a+json+b);download('PHIOS-WORLD-EXPERIENCE-R2-PUBLIC.html',html,'text/html;charset=utf-8');toast(T('publicSaved'))}
function pageReport(){return {kind:'PHIOS_WORLD_EXPERIENCE_R2_REVIEW_REPORT',createdAt:new Date().toISOString(),sourceCommit:null,sourceIdentity:SHA,publicContext:publicContext(),caseDirectory:db.cases.length,casesWithLoadedText:db.cases.filter(readable).length,assetRecords:db.assets.length,assetCountIsCurrentBucketTotal:false,verifiedLocalImages:localImages.size,originalBookFigures:Object.keys(FIGURES).length,originalsNotLanguageVerified:true,geographicFeatures:GEO.length,mapVintageUnverified:true,statistics:[...observations.values()].map(o=>({...o})),importReport,privateInputsIncluded:false,modelCalls:0,accountResultsLoaded:false,productionHandoffVerified:false,repositoryWrites:0,productionWrites:0,buildLiveNetworkVerification:false}}

