let selectedPreset='';
function renderPresets(){let el=$('#questionPresets');if(el)el.innerHTML=`<summary>${pair('从一个生活问题开始','Start with an everyday question')}</summary><div class="preset-grid">${PRESETS.map(p=>button('preset',vtext(p.q),`data-id="${p.id}" aria-pressed="${selectedPreset===p.id}"`)).join('')}</div>`}
function focusWorkspace(){$('#workspace').scrollIntoView({behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'start'})}
function openOriginal(id){let f=FIGURES[id];if(!f?.variants?.[getLocale()]?.publicUrl){toast(T('readFailed'));return;}openModal(figureLabel(id),`<p class="note">${T('originalNote')}</p><div class="actions"><button data-action="originalFit">${pair('适合屏幕','Fit screen')}</button><button data-action="originalFull">${pair('原始宽度','Original width')}</button></div><div class="original-scroll" style="overflow:auto;margin-top:15px"><img id="originalImage" src="${f.variants?.[getLocale()]?.publicUrl||f.src}" alt="${esc(figureLabel(id))}" style="display:block;width:100%;height:auto;margin:auto;max-width:1600px"></div><p class="small muted">${T('originalPreserved')}</p>`)}
function languageChange(){clearTimeout(toast.timer);$('#toast').hidden=true;$('#toast').textContent='';if($('#modal').open)closeModal();state.lang=state.lang==='zh'?'en':'zh';if(selectedPreset){let wasBound=privateBoundContext===JSON.stringify([state.region,state.topic,state.year,state.baseline,state.scale,state.perspective,state.caseId,state.caseRight,state.snapshot,customQuestion]);customQuestion=vtext(PRESETS.find(p=>p.id===selectedPreset).q);if(wasBound)privateBoundContext=contextSignature()}dataRequestState='';$('#importStatus').textContent='';render();}
function enableConsent(){if(!Object.values(consent).some(Boolean)){toast(T('consentNeeded'));return}consentGranted=true;privatePreview=false;privateBoundContext=contextSignature();render();$('#privateSelf')?.focus()}
function choosePreset(id){evidenceIntent='';evidenceQuarter='';const p=PRESETS.find(x=>x.id===id);if(!p)return;selectedPreset=id;customQuestion=vtext(p.q);searchResults=null;setPublic({topic:p.topic,region:p.region||state.region,space:'explore',mode:'current',pane:'map'});focusWorkspace()}
async function act(action,e){const d=e?.dataset||{};switch(action){
 case 'language':setLocale(state.lang==='zh'?'en':'zh-Hans');break;
 case 'explore':case 'returnWorld':setPublic({space:'explore'});focusWorkspace();break;
 case 'me':setPublic({space:'me',origin:'world'});focusWorkspace();break;
 case 'fromMethod':setPublic({space:'me',origin:'method'});focusWorkspace();break;
 case 'quick':if(d.target==='me'){setPublic({space:'me',origin:'world'})}else if(d.target==='economy'){customQuestion='';selectedPreset='';setPublic({space:'explore',mode:'current',pane:'map',topic:'economy'})}else go({history:'cases',compare:'places'}[d.target]||d.target);focusWorkspace();break;
 case 'reset':evidenceIntent='';evidenceQuarter='';customQuestion='';selectedPreset='';searchText='';searchResults=null;mapZoom=1;mapPan=0;setPublic({region:'GLOBAL',topic:'connections',year:2026,baseline:'IDN',scale:'place',perspective:'general',space:'explore',mode:'current',pane:'map'});toast(T('resetWarning'));break;
 case 'mode':if(['current','history','compare'].includes(d.mode))setPublic({space:'explore',mode:d.mode,pane:{current:'map',history:'cases',compare:'places'}[d.mode]});break;
 case 'pane':go(d.pane);break;
 case 'topic':if(TOPICS[d.topic]){evidenceIntent='';customQuestion='';selectedPreset='';setPublic({topic:d.topic})}break;
 case 'preset':choosePreset(d.id);break;
 case 'sourceCatalogue':{const d=document.querySelector('[data-world-native-details]');if(d)d.open=true;document.querySelector('#world-search')?.scrollIntoView({block:'start'});break;}
 case 'search':selectedPreset='';doSearch();break;
 case 'closeSearch':searchResults=null;render();break;
 case 'searchRegion':setPublic({region:d.id,space:'explore',mode:'current',pane:'map'});focusWorkspace();break;
 case 'compareArea':go('places');break;
 case 'relatedHistory':relatedHistory();break;
 case 'zoomIn':mapZoom=Math.min(6,mapZoom*1.4);applyMapTransform();saveHash();break;
 case 'zoomOut':mapZoom=Math.max(1,mapZoom/1.4);if(mapZoom===1)mapPan=0;applyMapTransform();saveHash();break;
 case 'focus':if(state.region==='GLOBAL')toast(T('choosePlace'));else {mapZoom=3;mapPan=0;applyMapTransform();saveHash()}break;
 case 'mapReset':mapZoom=1;mapPan=0;applyMapTransform();saveHash();break;
 case 'panLeft':mapPan+=120;applyMapTransform();saveHash();break;
 case 'panRight':mapPan-=120;applyMapTransform();saveHash();break;
 case 'case':chooseCase(d.case);break;
 case 'moreCases':state.caseLimit+=12;render();break;
 case 'compareCase':state.caseId=d.case;if(state.caseRight===state.caseId)state.caseRight=db.cases.find(c=>c.caseId!==state.caseId&&readable(c))?.caseId||db.cases[0].caseId;go('casecompare');focusWorkspace();break;
 case 'imageRole':if(['CASE_HERO','CASE_SECONDARY'].includes(d.role)){selectedImageRole=d.role;render();$('#caseReading')?.scrollIntoView({block:'start'})}break;
 case 'snapshot':if(db.snapshots.some(s=>s.snapshotId===d.id)){state.snapshot=d.id;render()}break;
 case 'book':state.book=+d.book;render();$('#bookDetail').scrollIntoView({behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'nearest'});break;
 case 'bookTopic':{let b=VOL.find(x=>x.n===state.book);if(b){customQuestion='';selectedPreset='';setPublic({space:'explore',topic:b.topic,mode:'current',pane:'map'});focusWorkspace()}break;}
 case 'bookFigures':{let id=Object.keys(FIGURES).find(k=>FIGURES[k].volume===state.book);if(id){state.fig=id;go('atlas');focusWorkspace()}break;}
 case 'allFigures':state.book=0;render();break;
 case 'figure':chooseFigure(d.id);break;
 case 'original':openOriginal(d.id);break;
 case 'originalFit':if($('#originalImage')){$('#originalImage').style.width='100%';$('#originalImage').style.maxWidth='1600px'}break;
 case 'originalFull':if($('#originalImage')){$('#originalImage').style.width=$('#originalImage').naturalWidth+'px';$('#originalImage').style.maxWidth='none'}break;
 case 'cell':state.cell=Number(d.cell);render();$('#figureDetail')?.querySelector('.model-detail')?.scrollIntoView({behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'nearest'});break;
 case 'scenario':state.scenario=Number(d.id)||0;render();break;
 case 'lifeFocus':if(LIFE[d.focus]){state.lifeFocus=d.focus;go('life')}break;
 case 'sources':showSources();break;
 case 'closeModal':closeModal();break;
 case 'readData':await readPublicData(false);break;
 case 'readCompareData':await readPublicData(true);break;
 case 'handoffAsk':{const historyMode=state.mode==='history';const ctx=worldAskContext(historyMode?'BOOK-5':'BOOK-6',historyMode?{activeLayer:'cases',primaryCaseId:state.caseId,caseIds:[state.caseId],time:state.year}:{activeLayer:'dossiers'},{cases:{cases:db.cases}},getLocale(),location.href);const url=askURL({...ctx,locale:getLocale()});if(!openEntryTarget(url,$('#askQuestion')?.value||q()))toast(pair('请允许打开提问入口。','Allow the question page to open.'));break;}
 case 'handoffNavigation':{if(!consentGranted||!navGranted||!privateIsCurrent())return;const draft=privateExport();const payload=JSON.stringify(draft);if(payload.length>2000){reviewPrivateExport();return;}if(draft&&!openEntryTarget('/reality/',payload))toast(T('readFailed'));break;}
 case 'askLocal':askQuestion=$('#askQuestion').value;$('#globalSearch').value=askQuestion;selectedPreset='';doSearch();break;
 case 'copyAsk':askQuestion=$('#askQuestion').value;await copyText((askQuestion||q())+'\n\n'+publicText(false));break;
 case 'applyConsent':enableConsent();break;
 case 'revoke':revoke();break;
 case 'reconfirm':privateBoundContext=contextSignature();privatePreview=false;render();break;
 case 'privatePreview':if(consentGranted&&privateIsCurrent()){privatePreview=true;render()}break;
 case 'startNavigation':if(!$('#navConsent')?.checked){toast(T('navConsent'));return}if(!privateIsCurrent()){toast(T('contextChanged'));return}navGranted=true;navStep='goal';render();$('#navText')?.focus();break;
 case 'navStep':if(['goal','options','attempt','result','review'].includes(d.step)&&navGranted){navStep=d.step;render();$('#navText')?.focus()}break;
 case 'reviewPrivateExport':reviewPrivateExport();break;
 case 'confirmPrivateExport':if(reviewExport&&consentGranted&&navGranted&&privateIsCurrent()){download('PHIOS-MY-NAVIGATION-NOTES.json',JSON.stringify(reviewExport,null,2));closeModal()}break;
 case 'importBundle':$('#bundleFile').click();break;
 case 'repoFolder':$('#repoFiles').click();break;
 case 'imageFolder':$('#imageFiles').click();break;
 case 'networkCatalog':await networkCatalog();break;
 case 'acceptVersion':if(pending){const p=pending;commitStage(p.next,p.docs,p.checks,true)}break;
 case 'cancelVersion':pending=null;$('#pendingVersion').hidden=true;$('#importStatus').textContent=pair('已取消，原有内容保持不变。','Cancelled. Existing content is unchanged.');break;
 case 'imageNetwork':remoteImages=!remoteImages;render();break;
 case 'savePublic':toast(pair('离线原件保留在审阅资料中。','The offline original is retained with the review materials.'));break;
 case 'downloadReport':download('PHIOS-WORLD-EXPERIENCE-R2-PAGE-STATUS.json',JSON.stringify(pageReport(),null,2));break;
 }}
host.addEventListener('click',ev=>{const art=ev.target.closest('[data-asset]');if(art){const a=db.assets.find(x=>x.assetId===art.dataset.asset),url=assetSource(a);if(url){activeRead=art;openModal(a.assetId,`<img src="${esc(url)}" alt="${esc(art.getAttribute('aria-label'))}"><p>${T('imageCaption')}</p>`)}return;}const b=ev.target.closest('[data-action]');if(b&&!b.disabled){ev.preventDefault();Promise.resolve(act(b.dataset.action,b)).catch(err=>{toast(pair('操作未完成；没有生成替代结果。','The operation did not complete; no substitute result was generated.'));console.warn('World review action failed:',err?.message)});return}const area=ev.target.closest('path.land[data-region]');if(area){setPublic({region:area.dataset.region});}});
